  1	import {
  2	  CrossAppNodeSchema,
  3	  CrossAppRelationTypeSchema,
  4	  CrossAppRelationTripleSchema,
  5	  CrossAppRelation,
  6	} from "../crossAppContracts";
  7	import { Tables, Json } from "../dbTypes";
  8	import type { DGSupabaseClient } from "./client";
  9	import { ridToSpaceUriAndLocalId, spaceUriAndLocalIdToRid, isRid } from "./rid";
 10	
 11	type Concept = Tables<"Concept">;
 12	
 13	const getConceptMap = async (
 14	  client: DGSupabaseClient,
 15	  conceptIds: number[],
 16	  spaceMap: Record<number, string>,
 17	): Promise<Record<number, string>> => {
 18	  if (conceptIds.length === 0) return {};
 19	  const request = await client
 20	    .from("my_concepts")
 21	    .select("id, space_id, source_local_id, is_schema, is_relation")
 22	    .in("id", conceptIds)
 23	    .not("source_local_id", "is", null);
 24	  if (request.error) throw request.error;
 25	  return Object.fromEntries(
 26	    (request.data || [])
 27	      // eslint-disable-next-line @typescript-eslint/naming-convention
 28	      .map(({ id, source_local_id, space_id, is_schema, is_relation }) => {
 29	        const spaceUri: string | undefined = spaceMap[space_id ?? 0];
 30	        return [
 31	          id!,
 32	          spaceUri !== undefined
 33	            ? spaceUriAndLocalIdToRid(
 34	                spaceUri,
 35	                source_local_id,
 36	                is_schema ? "schema" : is_relation ? "relation" : "note",
 37	              )
 38	            : undefined,
 39	        ];
 40	      })
 41	      .filter(([, rid]) => rid !== undefined) as [number, string][],
 42	  );
 43	};
 44	
 45	export const getAccountMap = async (
 46	  client: DGSupabaseClient,
 47	  accountIds: number[],
 48	): Promise<Record<number, string>> => {
 49	  const request = await client
 50	    .from("my_accounts")
 51	    .select("id,account_local_id")
 52	    .in("id", accountIds);
 53	  if (request.error) throw request.error;
 54	  return Object.fromEntries(
 55	    (request.data || []).map(({ id, account_local_id }) => [
 56	      id!,
 57	      account_local_id!,
 58	    ]),
 59	  );
 60	};
 61	
 62	export const getSpaceMap = async (
 63	  client: DGSupabaseClient,
 64	  spaceIds?: number[],
 65	): Promise<Record<number, string>> => {
 66	  let query = client.from("my_spaces").select("id, url");
 67	  if (spaceIds !== undefined) query = query.in("id", [...spaceIds]);
 68	
 69	  const { data, error } = await query;
 70	  if (error) throw error;
 71	  if (!data) throw new Error("Missing spaces");
 72	  return Object.fromEntries(data.map(({ id, url }) => [id!, url!]));
 73	};
 74	
 75	const asSimpleLocalId = (
 76	  rid: string | undefined,
 77	  spaceUrl: string | undefined,
 78	  optional?: boolean,
 79	): string | undefined => {
 80	  if (rid === undefined) return undefined;
 81	  if (!isRid(rid)) return rid;
 82	  const { spaceUri, sourceLocalId } = ridToSpaceUriAndLocalId(rid);
 83	  if (spaceUrl === spaceUri) return sourceLocalId;
 84	  if (optional !== true) throw new Error("Unexpected spaceUri");
 85	  return rid;
 86	};
 87	
 88	export const dbNodeSchemaToCrossApp = ({
 89	  schema,
 90	  spaceMap,
 91	  accountMap,
 92	  schemaMap,
 93	}: {
 94	  schema: Concept;
 95	  spaceMap: Record<number, string>;
 96	  accountMap: Record<number, string>;
 97	  schemaMap: Record<number, string>;
 98	}): CrossAppNodeSchema => {
 99	  const referenceContent = (schema.reference_content ?? {}) as Record<
100	    string,
101	    number
102	  >;
103	  const { template, template_content, roles, format, ...other } =
104	    schema.literal_content as Record<string, Json>;
105	  const authorId = accountMap[schema.author_id || 0];
106	  if (authorId === undefined) throw new Error("Missing author");
107	  const spaceUrl = spaceMap[schema.space_id];
108	  if (spaceUrl === undefined) throw new Error("Missing space");
109	  const rid = spaceUriAndLocalIdToRid(
110	    spaceUrl,
111	    schema.source_local_id!,
112	    "schema",
113	  );
114	  const slotDefinitions = Object.fromEntries(
115	    ((roles as string[] | undefined) ?? []).map((r) => [
116	      r,
117	      asSimpleLocalId(schemaMap[referenceContent[r] ?? 0], spaceUrl),
118	    ]),
119	  );
120	  return {
121	    rid,
122	    localId: schema.source_local_id!,
123	    createdAt: new Date(schema.created + "Z"),
124	    modifiedAt: new Date(schema.last_modified + "Z"),
125	    label: schema.name,
126	    metadata: other,
127	    template: template_content as string | undefined,
128	    templateTitle: template as string | undefined,
129	    format: format as string | undefined,
130	    authorId,
131	    slotDefinitions,
132	  };
133	};
134	
135	export const dbNodeSchemasToCrossApp = async ({
136	  client,
137	  schemas,
138	  spaceMap,
139	  accountMap,
140	}: {
141	  client: DGSupabaseClient;
142	  schemas: Concept[];
143	  spaceMap?: Record<number, string>;
144	  accountMap?: Record<number, string>;
145	}): Promise<CrossAppNodeSchema[]> => {
146	  if (spaceMap === undefined) spaceMap = await getSpaceMap(client);
147	  if (accountMap === undefined) {
148	    const authorIds = new Set<number>(
149	      schemas.map((r) => r.author_id).filter((id) => typeof id === "number"),
150	    );
151	    accountMap = await getAccountMap(client, [...authorIds]);
152	  }
153	  const referredSchemaIds = schemas.flatMap((schema) => schema.refs);
154	  const schemaMap = await getConceptMap(client, referredSchemaIds, spaceMap);
155	  return schemas.map((schema) =>
156	    dbNodeSchemaToCrossApp({ schema, spaceMap, accountMap, schemaMap }),
157	  );
158	};
159	
160	export const dbRelationTypeSchemaToCrossApp = (
161	  schema: Concept,
162	  spaceMap: Record<number, string>,
163	  accountMap: Record<number, string>,
164	): CrossAppRelationTypeSchema => {
165	  // eslint-disable-next-line @typescript-eslint/no-unused-vars
166	  const { roles, label, complement, ...other } =
167	    schema.literal_content as Record<string, Json>;
168	  const authorId = accountMap[schema.author_id || 0];
169	  if (authorId === undefined) throw new Error("Missing author");
170	  const spaceUrl = spaceMap[schema.space_id];
171	  if (spaceUrl === undefined) throw new Error("Missing space");
172	  const rid = spaceUriAndLocalIdToRid(
173	    spaceUrl,
174	    schema.source_local_id!,
175	    "schema",
176	  );
177	  return {
178	    rid,
179	    localId: schema.source_local_id!,
180	    createdAt: new Date(schema.created + "Z"),
181	    modifiedAt: new Date(schema.last_modified + "Z"),
182	    metadata: other,
183	    label: label as string,
184	    complement: complement as string,
185	    authorId,
186	  };
187	};
188	
189	export const dbRelationTypeSchemasToCrossApp = async ({
190	  client,
191	  schemas,
192	  spaceMap,
193	  accountMap,
194	}: {
195	  client: DGSupabaseClient;
196	  schemas: Concept[];
197	  spaceMap?: Record<number, string>;
198	  accountMap?: Record<number, string>;
199	}): Promise<CrossAppRelationTypeSchema[]> => {
200	  if (spaceMap === undefined) spaceMap = await getSpaceMap(client);
201	  if (accountMap === undefined) {
202	    const authorIds = new Set<number>(
203	      schemas.map((r) => r.author_id).filter((id) => typeof id === "number"),
204	    );
205	    accountMap = await getAccountMap(client, [...authorIds]);
206	  }
207	
208	  return schemas.map((r) =>
209	    dbRelationTypeSchemaToCrossApp(r, spaceMap, accountMap),
210	  );
211	};
212	
213	export const dbRelationTripleSchemaToCrossApp = ({
214	  schema,
215	  spaceMap,
216	  accountMap,
217	  conceptMap,
218	}: {
219	  schema: Concept;
220	  spaceMap: Record<number, string>;
221	  accountMap: Record<number, string>;
222	  conceptMap: Record<number, string>;
223	}): CrossAppRelationTripleSchema => {
224	  // eslint-disable-next-line @typescript-eslint/no-unused-vars
225	  const { roles, label, complement, ...other } =
226	    schema.literal_content as Record<string, Json>;
227	  const authorId = accountMap[schema.author_id || 0];
228	  if (authorId === undefined) throw new Error("Missing author");
229	  const references = (schema.reference_content ?? {}) as Record<string, number>;
230	  const spaceUrl = spaceMap[schema.space_id];
231	  if (spaceUrl === undefined) throw new Error("Missing space");
232	  const rid = spaceUriAndLocalIdToRid(
233	    spaceUrl,
234	    schema.source_local_id!,
235	    "schema",
236	  );
237	  const relation = asSimpleLocalId(
238	    conceptMap[references["relation_type"] ?? 0],
239	    spaceUrl,
240	  );
241	  const sourceType = asSimpleLocalId(
242	    conceptMap[references["source"] ?? 0],
243	    spaceUrl,
244	  );
245	  const destinationType = asSimpleLocalId(
246	    conceptMap[references["destination"] ?? 0],
247	    spaceUrl,
248	  );
249	  if (sourceType === undefined) throw new Error("Missing source type");
250	  if (destinationType === undefined)
251	    throw new Error("Missing destination type");
252	  const base = {
253	    rid,
254	    localId: schema.source_local_id!,
255	    createdAt: new Date(schema.created + "Z"),
256	    modifiedAt: new Date(schema.last_modified + "Z"),
257	    metadata: other,
258	    authorId,
259	    sourceType,
260	    destinationType,
261	  };
262	  if (relation) {
263	    return {
264	      ...base,
265	      relation,
266	    };
267	  } else {
268	    if (typeof label !== "string" || typeof complement !== "string")
269	      throw new Error("Missing either relation_type or relation_type data");
270	    return {
271	      ...base,
272	      label,
273	      complement,
274	    };
275	  }
276	};
277	
278	export const dbRelationTripleSchemasToCrossApp = async ({
279	  client,
280	  schemas,
281	  spaceMap,
282	  accountMap,
283	  conceptMap,
284	}: {
285	  client: DGSupabaseClient;
286	  schemas: Concept[];
287	  spaceMap?: Record<number, string>;
288	  accountMap?: Record<number, string>;
289	  conceptMap?: Record<number, string>;
290	}): Promise<CrossAppRelationTripleSchema[]> => {
291	  if (spaceMap === undefined) spaceMap = await getSpaceMap(client);
292	  if (accountMap === undefined) {
293	    const authorIds = new Set<number>(
294	      schemas.map((r) => r.author_id).filter((id) => typeof id === "number"),
295	    );
296	    accountMap = await getAccountMap(client, [...authorIds]);
297	  }
298	  if (conceptMap === undefined) {
299	    const schemaIds = schemas
300	      .map((r) => {
301	        const refs = (r.reference_content ?? {}) as Record<
302	          string,
303	          number | number[]
304	        >;
305	        return [
306	          refs["source"] ?? [],
307	          refs["destination"] ?? [],
308	          refs["relation_type"] ?? [],
309	        ];
310	      })
311	      .flat(2);
312	    conceptMap = await getConceptMap(client, [...new Set(schemaIds)], spaceMap);
313	  }
314	
315	  return schemas.map((schema) =>
316	    dbRelationTripleSchemaToCrossApp({
317	      schema,
318	      spaceMap,
319	      accountMap,
320	      conceptMap,
321	    }),
322	  );
323	};
324	
325	export const dbRelationToCrossApp = ({
326	  relation,
327	  spaceMap,
328	  accountMap,
329	  conceptMap,
330	}: {
331	  relation: Concept;
332	  spaceMap: Record<number, string>;
333	  accountMap: Record<number, string>;
334	  conceptMap: Record<number, string>;
335	}): CrossAppRelation => {
336	  const authorId = accountMap[relation.author_id || 0];
337	  if (authorId === undefined) throw new Error("Missing author");
338	  const references = (relation.reference_content ?? {}) as Record<
339	    string,
340	    number
341	  >;
342	  const spaceUrl = spaceMap[relation.space_id];
343	  if (spaceUrl === undefined) throw new Error("Missing space");
344	  const rid = spaceUriAndLocalIdToRid(
345	    spaceUrl,
346	    relation.source_local_id!,
347	    "relation",
348	  );
349	  const relationType = asSimpleLocalId(
350	    conceptMap[relation.schema_id || 0],
351	    spaceUrl,
352	  );
353	  if (relationType === undefined) throw new Error("Missing relationType");
354	  const source = asSimpleLocalId(
355	    conceptMap[references["source"] || 0],
356	    spaceUrl,
357	    true,
358	  );
359	  if (source === undefined) throw new Error("Missing source");
360	  const destination = asSimpleLocalId(
361	    conceptMap[references["destination"] || 0],
362	    spaceUrl,
363	    true,
364	  );
365	  if (destination === undefined) throw new Error("Missing destination");
366	
367	  return {
368	    rid,
369	    localId: relation.source_local_id!,
370	    authorId,
371	    createdAt: new Date(relation.created + "Z"),
372	    modifiedAt: new Date(relation.last_modified + "Z"),
373	    source,
374	    destination,
375	    relationType,
376	  };
377	};
378	
379	export const dbRelationsToCrossApp = async ({
380	  client,
381	  relations,
382	  accountMap,
383	  conceptMap,
384	  spaceMap,
385	}: {
386	  client: DGSupabaseClient;
387	  relations: Concept[];
388	  accountMap?: Record<number, string>;
389	  conceptMap?: Record<number, string>;
390	  spaceMap?: Record<number, string>;
391	}): Promise<CrossAppRelation[]> => {
392	  if (accountMap === undefined) {
393	    const authorIds = new Set<number>(
394	      relations.map((r) => r.author_id).filter((id) => typeof id === "number"),
395	    );
396	    accountMap = await getAccountMap(client, [...authorIds]);
397	  }
398	  if (spaceMap === undefined) {
399	    spaceMap = await getSpaceMap(client);
400	  }
401	  if (conceptMap === undefined) {
402	    const nodeIds = relations
403	      .map((r) => {
404	        const refs = (r.reference_content ?? {}) as Record<
405	          string,
406	          number | number[]
407	        >;
408	        return [refs["source"] ?? [], refs["destination"] ?? []];
409	      })
410	      .flat(2);
411	    const schemaIds = relations
412	      .map((r) => r.schema_id)
413	      .filter((id) => id !== null);
414	    conceptMap = await getConceptMap(
415	      client,
416	      [...new Set([...schemaIds, ...nodeIds])],
417	      spaceMap,
418	    );
419	  }
420	  return relations.map((relation) =>
421	    dbRelationToCrossApp({ relation, spaceMap, accountMap, conceptMap }),
422	  );
423	};

