 45	export const getAccountMap = async (
 46	  client: DGSupabaseClient,
 47	  accountIds: number[],
 48	): Promise<Record<number, string>> => {
 49	  const request = await client
 50	    .from("my_accounts")
 51	    .select("id,account_local_id")
 52	    .in("id", accountIds);
 53	  if (request.error) throw request.error;
 54	  return Object.fromEntries(
 55	    (request.data || []).map(({ id, account_local_id }) => [
 56	      id!,
 57	      account_local_id!,
 58	    ]),
 59	  );
