213	export const dbRelationTripleSchemaToCrossApp = ({
214	  schema,
215	  spaceMap,
216	  accountMap,
217	  conceptMap,
218	}: {
219	  schema: Concept;
220	  spaceMap: Record<number, string>;
221	  accountMap: Record<number, string>;
222	  conceptMap: Record<number, string>;
223	}): CrossAppRelationTripleSchema => {
224	  // eslint-disable-next-line @typescript-eslint/no-unused-vars
225	  const { roles, label, complement, ...other } =
226	    schema.literal_content as Record<string, Json>;
227	  const authorId = accountMap[schema.author_id || 0];
228	  if (authorId === undefined) throw new Error("Missing author");
229	  const references = (schema.reference_content ?? {}) as Record<string, number>;
230	  const spaceUrl = spaceMap[schema.space_id];
231	  if (spaceUrl === undefined) throw new Error("Missing space");
232	  const rid = spaceUriAndLocalIdToRid(
233	    spaceUrl,
234	    schema.source_local_id!,
235	    "schema",
236	  );
237	  const relation = asSimpleLocalId(
238	    conceptMap[references["relation_type"] ?? 0],
239	    spaceUrl,
240	  );
241	  const sourceType = asSimpleLocalId(
242	    conceptMap[references["source"] ?? 0],
243	    spaceUrl,
244	  );
245	  const destinationType = asSimpleLocalId(
246	    conceptMap[references["destination"] ?? 0],
247	    spaceUrl,
248	  );
249	  if (sourceType === undefined) throw new Error("Missing source type");
250	  if (destinationType === undefined)
251	    throw new Error("Missing destination type");
252	  const base = {
253	    rid,
254	    localId: schema.source_local_id!,
255	    createdAt: new Date(schema.created + "Z"),
256	    modifiedAt: new Date(schema.last_modified + "Z"),
257	    metadata: other,
258	    authorId,
259	    sourceType,
260	    destinationType,
261	  };
262	  if (relation) {
263	    return {
264	      ...base,
265	      relation,
266	    };
267	  } else {
268	    if (typeof label !== "string" || typeof complement !== "string")
269	      throw new Error("Missing either relation_type or relation_type data");
270	    return {
271	      ...base,
272	      label,
273	      complement,
274	    };
275	  }
276	};
