325	export const dbRelationToCrossApp = ({
326	  relation,
327	  spaceMap,
328	  accountMap,
329	  conceptMap,
330	}: {
331	  relation: Concept;
332	  spaceMap: Record<number, string>;
333	  accountMap: Record<number, string>;
334	  conceptMap: Record<number, string>;
335	}): CrossAppRelation => {
336	  const authorId = accountMap[relation.author_id || 0];
337	  if (authorId === undefined) throw new Error("Missing author");
338	  const references = (relation.reference_content ?? {}) as Record<
339	    string,
340	    number
341	  >;
342	  const spaceUrl = spaceMap[relation.space_id];
343	  if (spaceUrl === undefined) throw new Error("Missing space");
344	  const rid = spaceUriAndLocalIdToRid(
345	    spaceUrl,
346	    relation.source_local_id!,
347	    "relation",
348	  );
349	  const relationType = asSimpleLocalId(
350	    conceptMap[relation.schema_id || 0],
351	    spaceUrl,
352	  );
353	  if (relationType === undefined) throw new Error("Missing relationType");
354	  const source = asSimpleLocalId(
355	    conceptMap[references["source"] || 0],
356	    spaceUrl,
357	    true,
358	  );
359	  if (source === undefined) throw new Error("Missing source");
360	  const destination = asSimpleLocalId(
361	    conceptMap[references["destination"] || 0],
362	    spaceUrl,
363	    true,
364	  );
365	  if (destination === undefined) throw new Error("Missing destination");
366	
367	  return {
368	    rid,
369	    localId: relation.source_local_id!,
370	    authorId,
371	    createdAt: new Date(relation.created + "Z"),
372	    modifiedAt: new Date(relation.last_modified + "Z"),
373	    source,
374	    destination,
375	    relationType,
376	  };
