379	export const dbRelationsToCrossApp = async ({
380	  client,
381	  relations,
382	  accountMap,
383	  conceptMap,
384	  spaceMap,
385	}: {
386	  client: DGSupabaseClient;
387	  relations: Concept[];
388	  accountMap?: Record<number, string>;
389	  conceptMap?: Record<number, string>;
390	  spaceMap?: Record<number, string>;
391	}): Promise<CrossAppRelation[]> => {
392	  if (accountMap === undefined) {
393	    const authorIds = new Set<number>(
394	      relations.map((r) => r.author_id).filter((id) => typeof id === "number"),
395	    );
396	    accountMap = await getAccountMap(client, [...authorIds]);
397	  }
398	  if (spaceMap === undefined) {
399	    spaceMap = await getSpaceMap(client);
400	  }
401	  if (conceptMap === undefined) {
402	    const nodeIds = relations
403	      .map((r) => {
404	        const refs = (r.reference_content ?? {}) as Record<
405	          string,
406	          number | number[]
407	        >;
408	        return [refs["source"] ?? [], refs["destination"] ?? []];
409	      })
410	      .flat(2);
411	    const schemaIds = relations
412	      .map((r) => r.schema_id)
413	      .filter((id) => id !== null);
414	    conceptMap = await getConceptMap(
415	      client,
416	      [...new Set([...schemaIds, ...nodeIds])],
417	      spaceMap,
418	    );
419	  }
420	  return relations.map((relation) =>
421	    dbRelationToCrossApp({ relation, spaceMap, accountMap, conceptMap }),
422	  );
423	};

