  4	// An identifier for objects in the platform. Expected to be unique within the platform.
  5	export type LocalId = string;
  6	
  7	// A composite identifier for objects in other spaces.
  8	export type Rid = string;
  9	
 10	// Common attributes for most types
 11	export type CrossAppBase = {
 12	  localId: LocalId;
 13	  rid?: string;
 14	  createdAt: Date;
 15	  modifiedAt?: Date;
 16	  authorId: LocalId;
 17	};
 18	
 19	export type CrossAppSchemaBase = CrossAppBase & {
 20	  metadata?: Json;
 21	};
 22	
 23	// A node schema
 24	export type CrossAppNodeSchema = CrossAppSchemaBase & {
 25	  label: string;
 26	  template?: string;
 27	  templateTitle?: string;
 28	  format?: string;
 29	  slotDefinitions?: Record<string, LocalId | undefined>;
 30	};
 31	
 32	// A relation type schema
 33	export type CrossAppRelationTypeSchema = CrossAppSchemaBase & {
 34	  label: string;
 35	  complement: string;
 36	  // should we add colour? format?
 37	};
 38	
 39	// A relation triple schema
 40	export type CrossAppRelationTripleSchema = CrossAppSchemaBase &
 41	  (
 42	    | {
 43	        label: string;
 44	        complement: string;
 45	        relation?: never;
 46	      }
 47	    | {
 48	        relation: LocalId;
 49	        label?: never;
 50	        complement?: never;
 51	      }
 52	  ) & {
 53	    sourceType: LocalId;
 54	    destinationType: LocalId;
 55	  };
 56	
 57	// An inline vector semantic embedding
 58	export type CrossAppEmbedding = {
 59	  value: number[];
 60	  embedding?: Enums<"EmbeddingName">;
 61	};
 62	
 63	// A Content object. It can be put inline inside a concept.
 64	// Missing CrossAppBase attributes are inferred from enclosing object.
 65	export type InlineCrossAppContent = Partial<CrossAppBase> & {
 66	  value: string;
 67	  embedding?: CrossAppEmbedding;
 68	  scale?: Enums<"Scale">;
 69	  contentType?: ContentType;
 70	};
 71	
 72	// An inline Content with obligatory typing
 73	type InlineCrossAppTypedContent = InlineCrossAppContent & {
 74	  contentType: ContentType;
 75	};
 76	
 77	// An asset (an image or attachment) that a node's full content references.
 78	export type CrossAppAsset = {
 79	  // What the full content refers to, exactly as written: a path on a platform that
 80	  // addresses assets by path, a URL on one that addresses them by URL. Publication
 81	  // never rewrites it, so a destination matches on it. Unique within one node's
 82	  // `assets`: it maps to `FileReference.filepath`, part of that table's primary key.
 83	  sourceRef: string;
 84	  // SHA-256 of the stored bytes as 64 lowercase hex characters, which is also their
 85	  // object name in shared storage. A destination looks the bytes up by this string
 86	  // exactly, so any other encoding fails as a not-found rather than a type error.
 87	  // Required: an asset whose bytes were not stored is absent from `assets` rather than
 88	  // present with nothing to resolve, and the transfer that hit the failure reports it.
 89	  contentHash: string;
 90	  // Where the source kept the asset: a name on a platform with a flat asset namespace,
 91	  // a path on one with folders. A destination decomposes it as a path to name and place
 92	  // its local copy, and a bare name decomposes to itself. Absent when the source
 93	  // recorded nothing beyond `sourceRef`.
 94	  sourcePath?: string;
 95	};
 96	
 97	// A node instance
 98	export type CrossAppNode = CrossAppBase & {
 99	  nodeType: LocalId;
100	  // The title stripped of the node type's title format ("[[CLM]] - {content}"
101	  // -> the {content} part). Equals the title when the type has no format or
102	  // the title does not match it.
103	  coreTitle: string;
104	  slots?: Record<string, LocalId>;
105	  content: {
106	    direct: InlineCrossAppContent;
107	    full?: InlineCrossAppTypedContent;
108	  };
109	  // The assets referenced by `content.full` whose bytes are stored. One that could not
110	  // be stored is not listed, and a destination leaves its reference untouched, as it
111	  // does any link that was never an asset.
112	  assets?: CrossAppAsset[];
113	};
114	
115	// A relation instance
116	export type CrossAppRelation = CrossAppBase & {
117	  relationType: LocalId;
118	  /* eslint-disable @typescript-eslint/no-duplicate-type-constituents */
119	  source: LocalId | Rid;
120	  destination: LocalId | Rid;
121	  /* eslint-enable @typescript-eslint/no-duplicate-type-constituents */
122	};

